import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String word = next();
        int m = nextInt();
        List<String> answer = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            String sk = next();
            boolean[] have = new boolean[26];
            for (char c : sk.toCharArray())
                if (c != '-') have[c - 'a'] = true;
            boolean ok = true;
            int len = Math.min(sk.length(), word.length());
            for (int j = 0; j < len && ok; j++) {
                // A fixed letter must match; a hyphen must copy a letter the skeleton already has.
                if (sk.charAt(j) != '-') ok = sk.charAt(j) == word.charAt(j);
                else ok = have[word.charAt(j) - 'a'];
            }
            if (ok) answer.add(sk);
        }
        StringBuilder sb = new StringBuilder();
        sb.append(answer.size()).append('\n');
        for (String s : answer) sb.append(s).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	word := string(next())
	m := int(nextInt())
	var answer []string
	for i := 0; i < m; i++ {
		sk := string(next())
		var have [26]bool
		for j := 0; j < len(sk); j++ {
			if sk[j] != '-' {
				have[sk[j]-'a'] = true
			}
		}
		ok := true
		n := min(len(sk), len(word))
		for j := 0; j < n && ok; j++ {
			// A fixed letter must match; a hyphen must copy a letter the skeleton already has.
			if sk[j] != '-' {
				ok = sk[j] == word[j]
			} else {
				ok = have[word[j]-'a']
			}
		}
		if ok {
			answer = append(answer, sk)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(answer)) + "\n")
	for _, s := range answer {
		w.WriteString(s + "\n")
	}
}
